import {
  PRIORITY_META,
  STATUS_META,
  TYPE_META,
  type PriorityKey,
  type StatusKey,
  type TypeKey,
} from "@/lib/constants";

function metaColor(status: string) {
  return STATUS_META[status as StatusKey] ?? { label: status, color: "#B0B8C5", text: "#323A47" };
}

export function StatusBadge({ status }: { status: string }) {
  const meta = metaColor(status);
  return (
    <span className="badge" style={{ backgroundColor: meta.color, color: meta.text }}>
      {meta.label}
    </span>
  );
}

export function PriorityBadge({ priority }: { priority: string }) {
  const meta = PRIORITY_META[priority as PriorityKey] ?? {
    label: priority,
    color: "#B0B8C5",
    text: "#323A47",
  };
  return (
    <span className="badge" style={{ backgroundColor: meta.color, color: meta.text }}>
      {meta.label}
    </span>
  );
}

export function TypeBadge({ type }: { type: string }) {
  const meta = TYPE_META[type as TypeKey] ?? {
    label: type,
    color: "#F4F4F4",
    text: "#323A47",
  };
  return (
    <span className="badge" style={{ backgroundColor: meta.color, color: meta.text }}>
      {meta.label}
    </span>
  );
}

"use client";

import Link from "next/link";
import { usePathname } from "next/navigation";

type NavItem = { href: string; label: string; badge?: number };

export function Nav({ items }: { items: NavItem[] }) {
  const pathname = usePathname();

  return (
    <nav className="flex flex-wrap items-center gap-1">
      {items.map((item) => {
        const active = pathname === item.href || pathname.startsWith(`${item.href}/`);
        return (
          <Link
            key={item.href}
            href={item.href}
            className={[
              "rounded px-3 py-1.5 text-sm transition-colors",
              active ? "bg-white/10 text-white" : "text-white/70 hover:bg-white/5 hover:text-white",
            ].join(" ")}
          >
            {item.label}
            {item.badge ? (
              <span className="ml-1.5 inline-flex h-4 min-w-4 items-center justify-center rounded-full bg-brand-red px-1 text-[10px] font-bold text-white">
                {item.badge}
              </span>
            ) : null}
          </Link>
        );
      })}
    </nav>
  );
}

"use server";

import bcrypt from "bcryptjs";
import { redirect } from "next/navigation";
import { prisma } from "@/lib/db";
import { createSession, destroySession } from "@/lib/auth";

async function findValidUser(email: string, password: string) {
  const normalized = email.trim().toLowerCase();
  if (!normalized || !password) return null;

  const user = await prisma.user.findUnique({ where: { email: normalized } });
  if (!user) return null;

  const valid = await bcrypt.compare(password, user.passwordHash);
  return valid ? user : null;
}

export async function login(formData: FormData) {
  const email = String(formData.get("email") ?? "");
  const password = String(formData.get("password") ?? "");

  const user = await findValidUser(email, password);
  if (!user) redirect("/login?error=credentials");

  await createSession(user.id);
  redirect("/appeals");
}

export async function quickLogin(formData: FormData) {
  const email = String(formData.get("email") ?? "");
  const user = await findValidUser(email, "demo1234");
  if (!user) redirect("/login?error=demo");

  await createSession(user.id);
  redirect("/appeals");
}

export async function logout() {
  await destroySession();
  redirect("/login");
}

