import type { Appeal, User } from "@prisma/client";

type ScopedUser = Pick<User, "id" | "role" | "departmentId">;
type ScopedAppeal = Pick<Appeal, "authorId" | "assigneeId" | "departmentId" | "responsibleId">;

export function isAdmin(user: ScopedUser): boolean {
  return user.role === "admin";
}

export function isAuthor(user: ScopedUser, appeal: ScopedAppeal): boolean {
  return appeal.authorId === user.id;
}

export function isAssignee(user: ScopedUser, appeal: ScopedAppeal): boolean {
  return appeal.assigneeId === user.id;
}

export function canManageAppeal(user: ScopedUser, appeal: ScopedAppeal): boolean {
  if (user.role === "admin") return true;
  if (user.role !== "head") return false;
  return appeal.departmentId === user.departmentId || appeal.responsibleId === user.id;
}

"use server";

import { notFound } from "next/navigation";
import { revalidatePath } from "next/cache";
import { requireUser } from "@/lib/auth";
import { prisma } from "@/lib/db";
import { SLA_DAYS, type PriorityKey } from "@/lib/constants";
import { canManageAppeal, isAssignee, isAuthor } from "@/lib/permissions";

const DAY = 86_400_000;

async function loadAppeal(id: string) {
  const user = await requireUser();
  const appeal = await prisma.appeal.findUnique({
    where: { id },
    include: { department: true },
  });
  if (!appeal) notFound();
  return { user, appeal };
}

function refresh(id: string) {
  revalidatePath(`/appeals/${id}`);
  revalidatePath("/appeals");
  revalidatePath("/analytics");
  revalidatePath("/notifications");
}

export async function acceptAppeal(formData: FormData) {
  const id = String(formData.get("appealId") ?? "");
  const { user, appeal } = await loadAppeal(id);

  if (!canManageAppeal(user, appeal) || appeal.status !== "new") return;

  const now = new Date();
  await prisma.$transaction([
    prisma.appeal.update({
      where: { id },
      data: { status: "review", firstResponseAt: appeal.firstResponseAt ?? now },
    }),
    prisma.appealHistory.create({
      data: {
        appealId: id,
        actorId: user.id,
        event: "status_changed",
        fromStatus: "new",
        toStatus: "review",
        comment: "Принято в рассмотрение",
        createdAt: now,
      },
    }),
    prisma.notification.create({
      data: {
        userId: appeal.authorId,
        appealId: id,
        event: "review",
        message: `Обращение ${appeal.code} принято в рассмотрение`,
      },
    }),
  ]);

  refresh(id);
}

export async function assignAppeal(formData: FormData) {
  const id = String(formData.get("appealId") ?? "");
  const assigneeId = String(formData.get("assigneeId") ?? "");
  const deadlineRaw = String(formData.get("deadline") ?? "");
  const { user, appeal } = await loadAppeal(id);

  if (!canManageAppeal(user, appeal) || appeal.status !== "review" || !assigneeId) return;

  const assignee = await prisma.user.findFirst({
    where: { id: assigneeId, departmentId: appeal.departmentId ?? undefined },
  });
  if (!assignee) return;

  const slaDays = SLA_DAYS[appeal.priority as PriorityKey] ?? 7;
  const deadline = deadlineRaw
    ? new Date(`${deadlineRaw}T18:00:00`)
    : new Date(Date.now() + slaDays * DAY);

  const now = new Date();
  await prisma.$transaction([
    prisma.appeal.update({
      where: { id },
      data: {
        status: "in_work",
        assigneeId,
        deadline,
        firstResponseAt: appeal.firstResponseAt ?? now,
      },
    }),
    prisma.appealHistory.create({
      data: {
        appealId: id,
        actorId: user.id,
        event: "assigned",
        fromStatus: "review",
        toStatus: "in_work",
        comment: `Исполнитель: ${assignee.name}. Срок: ${deadline.toLocaleDateString("ru-RU")}`,
        createdAt: now,
      },
    }),
    prisma.notification.createMany({
      data: [
        {
          userId: assignee.id,
          appealId: id,
          event: "assigned",
          message: `Вам назначено обращение ${appeal.code}: ${appeal.text.slice(0, 80)}`,
        },
        {
          userId: appeal.authorId,
          appealId: id,
          event: "in_work",
          message: `Обращение ${appeal.code} взято в работу`,
        },
      ],
    }),
  ]);

  refresh(id);
}

export async function requestClarification(formData: FormData) {
  const id = String(formData.get("appealId") ?? "");
  const text = String(formData.get("comment") ?? "").trim();
  const { user, appeal } = await loadAppeal(id);

  if (!canManageAppeal(user, appeal) || appeal.status !== "review" || text.length < 5) return;

  const now = new Date();
  await prisma.$transaction([
    prisma.appeal.update({
      where: { id },
      data: { status: "clarification", firstResponseAt: appeal.firstResponseAt ?? now },
    }),
    prisma.comment.create({
      data: { appealId: id, authorId: user.id, text, isClarification: true, createdAt: now },
    }),
    prisma.appealHistory.create({
      data: {
        appealId: id,
        actorId: user.id,
        event: "clarification",
        fromStatus: "review",
        toStatus: "clarification",
        comment: text,
        createdAt: now,
      },
    }),
    prisma.notification.create({
      data: {
        userId: appeal.authorId,
        appealId: id,
        event: "clarification",
        message: `По обращению ${appeal.code} требуется уточнение`,
      },
    }),
  ]);

  refresh(id);
}

export async function rejectAppeal(formData: FormData) {
  const id = String(formData.get("appealId") ?? "");
  const reason = String(formData.get("reason") ?? "").trim();
  const { user, appeal } = await loadAppeal(id);

  if (!canManageAppeal(user, appeal) || !["new", "review"].includes(appeal.status) || reason.length < 5) {
    return;
  }

  const now = new Date();
  await prisma.$transaction([
    prisma.appeal.update({
      where: { id },
      data: {
        status: "rejected",
        rejectReason: reason,
        firstResponseAt: appeal.firstResponseAt ?? now,
      },
    }),
    prisma.appealHistory.create({
      data: {
        appealId: id,
        actorId: user.id,
        event: "rejected",
        fromStatus: appeal.status,
        toStatus: "rejected",
        comment: reason,
        createdAt: now,
      },
    }),
    prisma.notification.create({
      data: {
        userId: appeal.authorId,
        appealId: id,
        event: "rejected",
        message: `Обращение ${appeal.code} отклонено. Причина в карточке обращения.`,
      },
    }),
  ]);

  refresh(id);
}

export async function resolveAppeal(formData: FormData) {
  const id = String(formData.get("appealId") ?? "");
  const result = String(formData.get("result") ?? "").trim();
  const { user, appeal } = await loadAppeal(id);

  const allowed = isAssignee(user, appeal) || user.role === "admin";
  if (!allowed || appeal.status !== "in_work" || result.length < 5) return;

  const now = new Date();
  await prisma.$transaction([
    prisma.appeal.update({
      where: { id },
      data: { status: "implemented", result, resolvedAt: now },
    }),
    prisma.appealHistory.create({
      data: {
        appealId: id,
        actorId: user.id,
        event: "resolved",
        fromStatus: "in_work",
        toStatus: "implemented",
        comment: result,
        createdAt: now,
      },
    }),
    prisma.notification.create({
      data: {
        userId: appeal.authorId,
        appealId: id,
        event: "implemented",
        message: `Обращение ${appeal.code} реализовано. Посмотрите итог и оцените результат.`,
      },
    }),
  ]);

  refresh(id);
}

export async function returnToHead(formData: FormData) {
  const id = String(formData.get("appealId") ?? "");
  const comment = String(formData.get("comment") ?? "").trim();
  const { user, appeal } = await loadAppeal(id);

  if (!isAssignee(user, appeal) || appeal.status !== "in_work" || comment.length < 5) return;

  const now = new Date();
  await prisma.$transaction([
    prisma.appeal.update({
      where: { id },
      data: { status: "review", assigneeId: null, deadline: null },
    }),
    prisma.appealHistory.create({
      data: {
        appealId: id,
        actorId: user.id,
        event: "status_changed",
        fromStatus: "in_work",
        toStatus: "review",
        comment: `Возврат начальнику: ${comment}`,
        createdAt: now,
      },
    }),
    prisma.notification.create({
      data: {
        userId: appeal.responsibleId ?? appeal.authorId,
        appealId: id,
        event: "returned",
        message: `Исполнитель вернул обращение ${appeal.code}: ${comment.slice(0, 100)}`,
      },
    }),
  ]);

  refresh(id);
}

export async function replyClarification(formData: FormData) {
  const id = String(formData.get("appealId") ?? "");
  const text = String(formData.get("reply") ?? "").trim();
  const { user, appeal } = await loadAppeal(id);

  if (!isAuthor(user, appeal) || appeal.status !== "clarification" || text.length < 3) return;

  const now = new Date();
  await prisma.$transaction([
    prisma.appeal.update({
      where: { id },
      data: { status: "review" },
    }),
    prisma.comment.create({
      data: { appealId: id, authorId: user.id, text, isClarification: false, createdAt: now },
    }),
    prisma.appealHistory.create({
      data: {
        appealId: id,
        actorId: user.id,
        event: "status_changed",
        fromStatus: "clarification",
        toStatus: "review",
        comment: text,
        createdAt: now,
      },
    }),
    prisma.notification.create({
      data: {
        userId: appeal.responsibleId ?? appeal.authorId,
        appealId: id,
        event: "clarified",
        message: `Автор ответил на уточнение по обращению ${appeal.code}`,
      },
    }),
  ]);

  refresh(id);
}

export async function rateAppeal(formData: FormData) {
  const id = String(formData.get("appealId") ?? "");
  const score = Number(formData.get("score") ?? 0);
  const { user, appeal } = await loadAppeal(id);

  if (!isAuthor(user, appeal) || !["implemented", "closed"].includes(appeal.status)) return;
  if (!Number.isInteger(score) || score < 1 || score > 5) return;

  const now = new Date();
  await prisma.$transaction([
    prisma.rating.upsert({
      where: { appealId: id },
      create: { appealId: id, authorId: user.id, score, createdAt: now },
      update: { score },
    }),
    prisma.appeal.update({
      where: { id },
      data: { status: "closed", closedAt: now },
    }),
    prisma.appealHistory.create({
      data: {
        appealId: id,
        actorId: user.id,
        event: "rated",
        fromStatus: appeal.status,
        toStatus: "closed",
        comment: `Оценка автора: ${score} из 5`,
        createdAt: now,
      },
    }),
    prisma.notification.create({
      data: {
        userId: appeal.assigneeId ?? appeal.responsibleId ?? user.id,
        appealId: id,
        event: "rated",
        message: `Обращение ${appeal.code} оценено на ${score} из 5 и закрыто`,
      },
    }),
  ]);

  refresh(id);
}

import type { CurrentUser } from "@/lib/auth";
import type { AppealDetail } from "@/lib/appeals";
import { SLA_DAYS, type PriorityKey } from "@/lib/constants";
import { canManageAppeal, isAssignee, isAuthor } from "@/lib/permissions";
import {
  acceptAppeal,
  assignAppeal,
  rateAppeal,
  rejectAppeal,
  replyClarification,
  requestClarification,
  resolveAppeal,
  returnToHead,
} from "@/app/(app)/appeals/[id]/actions";

const DAY = 86_400_000;

function isoDate(date: Date): string {
  return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, "0")}-${String(
    date.getDate(),
  ).padStart(2, "0")}`;
}

function ActionBox({
  title,
  tone = "default",
  children,
}: {
  title: string;
  tone?: "default" | "danger";
  children: React.ReactNode;
}) {
  return (
    <details className="group rounded border border-line">
      <summary className="cursor-pointer list-none px-3 py-2 text-sm font-medium text-ink hover:bg-[#FAFBFC]">
        <span className={tone === "danger" ? "text-[#E40000]" : ""}>{title}</span>
      </summary>
      <div className="space-y-2 border-t border-line p-3">{children}</div>
    </details>
  );
}

export function AppealActions({
  appeal,
  user,
  executors,
}: {
  appeal: AppealDetail;
  user: CurrentUser;
  executors: { id: string; name: string }[];
}) {
  const manage = canManageAppeal(user, appeal);
  const author = isAuthor(user, appeal);
  const assignee = isAssignee(user, appeal);
  const slaDays = SLA_DAYS[appeal.priority as PriorityKey] ?? 7;

  const blocks: React.ReactNode[] = [];

  if (manage && appeal.status === "new") {
    blocks.push(
      <form key="accept" action={acceptAppeal}>
        <input type="hidden" name="appealId" value={appeal.id} />
        <button type="submit" className="btn btn-primary w-full">
          Принять в рассмотрение
        </button>
        <p className="mt-2 text-xs text-muted">
          Автор получит уведомление, обращение перейдёт в статус «На рассмотрении».
        </p>
      </form>,
    );
  }

  if (manage && appeal.status === "review") {
    blocks.push(
      <ActionBox key="assign" title="Назначить исполнителя и срок">
        <form action={assignAppeal} className="space-y-2">
          <input type="hidden" name="appealId" value={appeal.id} />
          <div>
            <label className="label" htmlFor={`assignee-${appeal.id}`}>
              Исполнитель
            </label>
            <select id={`assignee-${appeal.id}`} name="assigneeId" required className="input">
              <option value="">Выберите сотрудника отдела</option>
              {executors.map((executor) => (
                <option key={executor.id} value={executor.id}>
                  {executor.name}
                </option>
              ))}
            </select>
          </div>
          <div>
            <label className="label" htmlFor={`deadline-${appeal.id}`}>
              Срок (по умолчанию +{slaDays} дн. по приоритету)
            </label>
            <input
              id={`deadline-${appeal.id}`}
              type="date"
              name="deadline"
              defaultValue={isoDate(new Date(Date.now() + slaDays * DAY))}
              className="input"
            />
          </div>
          <button type="submit" className="btn btn-primary w-full">
            Взять в работу
          </button>
        </form>
      </ActionBox>,
    );

    blocks.push(
      <ActionBox key="clarify" title="Запросить уточнение у автора">
        <form action={requestClarification} className="space-y-2">
          <input type="hidden" name="appealId" value={appeal.id} />
          <textarea
            name="comment"
            required
            minLength={5}
            rows={3}
            className="input resize-y"
            placeholder="Какой информации не хватает?"
          />
          <button type="submit" className="btn btn-secondary w-full">
            Отправить запрос
          </button>
        </form>
      </ActionBox>,
    );

    blocks.push(
      <ActionBox key="reject" title="Отклонить с мотивированным отказом" tone="danger">
        <form action={rejectAppeal} className="space-y-2">
          <input type="hidden" name="appealId" value={appeal.id} />
          <textarea
            name="reason"
            required
            minLength={5}
            rows={3}
            className="input resize-y"
            placeholder="Причина отказа, которую увидит автор"
          />
          <button type="submit" className="btn btn-secondary w-full">
            Отклонить обращение
          </button>
        </form>
      </ActionBox>,
    );
  }

  if ((assignee || user.role === "admin") && appeal.status === "in_work") {
    blocks.push(
      <ActionBox key="resolve" title="Зафиксировать итог и завершить">
        <form action={resolveAppeal} className="space-y-2">
          <input type="hidden" name="appealId" value={appeal.id} />
          <textarea
            name="result"
            required
            minLength={5}
            rows={3}
            className="input resize-y"
            placeholder="Что сделано и какой результат достигнут?"
          />
          <button type="submit" className="btn btn-primary w-full">
            Отметить выполненным
          </button>
        </form>
      </ActionBox>,
    );

    if (assignee) {
      blocks.push(
        <ActionBox key="return" title="Вернуть начальнику">
          <form action={returnToHead} className="space-y-2">
            <input type="hidden" name="appealId" value={appeal.id} />
            <textarea
              name="comment"
              required
              minLength={5}
              rows={3}
              className="input resize-y"
              placeholder="Почему не хватает данных для выполнения?"
            />
            <button type="submit" className="btn btn-secondary w-full">
              Вернуть с комментарием
            </button>
          </form>
        </ActionBox>,
      );
    }
  }

  if (author && appeal.status === "clarification") {
    blocks.push(
      <div key="reply">
        <p className="mb-2 text-sm text-ink">
          Начальник отдела запросил уточнение — ответьте, чтобы вернуть обращение в рассмотрение.
        </p>
        <form action={replyClarification} className="space-y-2">
          <input type="hidden" name="appealId" value={appeal.id} />
          <textarea
            name="reply"
            required
            minLength={3}
            rows={3}
            className="input resize-y"
            placeholder="Ваш ответ"
          />
          <button type="submit" className="btn btn-primary w-full">
            Отправить ответ
          </button>
        </form>
      </div>,
    );
  }

  if (author && appeal.status === "implemented") {
    blocks.push(
      <div key="rate">
        <p className="mb-2 text-sm text-ink">
          Итог зафиксирован. Оцените результат — обращение закроется.
        </p>
        <form action={rateAppeal} className="space-y-2">
          <input type="hidden" name="appealId" value={appeal.id} />
          <select name="score" className="input" defaultValue="5">
            <option value="5">5 — отлично</option>
            <option value="4">4 — хорошо</option>
            <option value="3">3 — нормально</option>
            <option value="2">2 — слабо</option>
            <option value="1">1 — плохо</option>
          </select>
          <button type="submit" className="btn btn-primary w-full">
            Оценить и закрыть
          </button>
        </form>
      </div>,
    );
  }

  if (blocks.length === 0) return null;

  return (
    <section className="card p-5">
      <h2 className="mb-3 text-sm font-bold uppercase tracking-wide text-brand">Действия</h2>
      <div className="space-y-3">{blocks}</div>
      {manage ? (
        <p className="mt-3 text-xs text-muted">
          Доступно начальнику отдела-получателя и администратору.
        </p>
      ) : null}
    </section>
  );
}

