await tools.browser.navigate({ tabID: tab.id, url: "http://localhost:3000/admin" });
await tools.browser.wait({ tabID: tab.id, condition: "text", text: "Администрирование" });
out.admin = (await tools.browser.evaluate({ tabID: tab.id, script: "document.body.innerText.slice(0,900)" })).value;
