const tab = (await tools.browser.tabs.list()).tabs[0];
const set = await tools.browser.evaluate({
  tabID: tab.id,
  script: `(() => {
    const rows = [...document.querySelectorAll('tbody tr')];
    const row = rows.find(r => r.innerText.includes('Интеграции и IT'));
    if (!row) return 'row not found';
    const form = row.querySelector('form');
    const select = form.querySelector('select');
    const opt = [...select.options].find(o => o.textContent.trim() === 'IT-разработка');
    select.value = opt.value;
    const before = select.options[select.selectedIndex].textContent;
    form.querySelector('button[type=submit]').click();
    return 'selected ' + before;
  })()`,
});
await tools.browser.wait({ tabID: tab.id, condition: "text", text: "IT-разработка" });
const after = await tools.browser.evaluate({
  tabID: tab.id,
  script: `(() => {
    const row = [...document.querySelectorAll('tbody tr')].find(r => r.innerText.includes('Интеграции и IT'));
    const select = row.querySelector('select');
    return select.options[select.selectedIndex].textContent;
  })()`,
});
return { set: set.value, after: after.value };

