input.content:
/* Шрифты подключаются с нашего сервера: внешние запросы к Google Fonts не нужны.
   Montserrat распространяется по лицензии SIL OFL 1.1 — текст в public/fonts/OFL-Montserrat.txt.
   Gilroy в репозиторий не включён: это коммерческий шрифт, файлы не лицензированы для
   публикации. Интерфейс использует Montserrat как совместимую замену. */
@font-face {
  font-family: "Montserrat";
  font-style: normal;
  font-weight: 400 700;
  font-display: swap;
  src: url("/fonts/montserrat-cyrillic.woff2") format("woff2");
  unicode-range: U+0301, U+0400-045F, U+0490-0491, U+04B0-04B1, U+2116;
}
@font-face {
  font-family: "Montserrat";
  font-style: normal;
  font-weight: 400 700;
  font-display: swap;
  src: url("/fonts/montserrat-latin.woff2") format("woff2");
  unicode-range: U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA, U+02DC,
    U+0304, U+0308, U+0329, U+2000-206F, U+20AC, U+2122, U+2191, U+2193, U+2212, U+2215,
    U+FEFF, U+FFFD;
}

@tailwind base;
@tailwind components;
@tailwind utilities;

@layer base {
  html {
    scroll-behavior: smooth;
  }
  body {
    @apply bg-canvas font-sans text-ink antialiased;
  }
  a {
    @apply text-link;
  }
  :focus-visible {
    outline: 2px solid #ed1111;
    outline-offset: 2px;
    border-radius: 2px;
  }
  ::selection {
    background: #ed1111;
    color: #fff;
  }
  @media (prefers-reduced-motion: reduce) {
    html {
      scroll-behavior: auto;
    }
    *,
    *::before,
    *::after {
      animation-duration: 0.01ms !important;
      animation-iteration-count: 1 !important;
      transition-duration: 0.01ms !important;
    }
  }
}

@layer components {
  .container-page {
    @apply mx-auto w-full max-w-6xl px-4 sm:px-6;
  }

  .card {
    @apply rounded-card border border-line bg-white;
  }

  /* Плоская панель без «коробки»: для списков и секций, где карточка не нужна. */
  .panel {
    @apply border-t border-line pt-6;
  }

  .btn {
    @apply inline-flex min-h-11 items-center justify-center gap-2 rounded px-5 py-2.5 text-[13px] font-semibold uppercase tracking-[0.01em] transition-colors disabled:cursor-not-allowed disabled:opacity-60;
  }
  .btn-primary {
    @apply bg-brand-red text-white hover:bg-brand-dark;
  }
  .btn-secondary {
    @apply border border-line bg-white text-ink hover:border-muted;
  }
  .btn-ghost {
    @apply text-ink hover:bg-canvas;
  }
  .btn-link {
    @apply inline-flex min-h-11 items-center gap-1 text-sm font-medium text-link hover:underline;
  }

  .input {
    @apply min-h-11 w-full rounded border border-line bg-white px-3 py-2 text-sm text-ink outline-none transition-colors placeholder:text-muted focus:border-brand-red;
  }
  .label {
    @apply mb-1 block text-[11px] font-semibold uppercase tracking-wide text-muted;
  }
  .field-error {
    @apply mt-1 text-xs font-medium text-[#C00000];
  }

  .badge {
    @apply inline-flex items-center rounded px-2 py-0.5 text-[11px] font-semibold leading-5;
  }

  .th {
    @apply whitespace-nowrap px-3 py-2 text-left text-[11px] font-semibold uppercase tracking-wide text-muted;
  }
  .td {
    @apply px-3 py-3 align-top text-sm;
  }

  .info-block {
    @apply rounded border border-line border-l-4 border-l-[#2F80ED] bg-info p-4;
  }
  .danger-block {
    @apply rounded border border-line border-l-4 border-l-[#E40000] bg-white p-4;
  }

  /* Три уровня отступов: внутри 8, между 24, между секциями 64. */
  .stack-tight > * + * {
    @apply mt-2;
  }
  .stack > * + * {
    @apply mt-6;
  }
  .stack-section > * + * {
    @apply mt-16;
  }

  .skip-link {
    @apply absolute left-4 top-3 z-50 -translate-y-20 rounded bg-white px-4 py-2 text-sm font-semibold text-brand shadow transition-transform focus:translate-y-0;
  }

  .skeleton {
    @apply relative overflow-hidden rounded bg-[#E9EBEF];
  }
  .skeleton::after {
    content: "";
    position: absolute;
    inset: 0;
    transform: translateX(-100%);
