"use client";

import { useEffect, useState } from "react";
import Link from "next/link";

const STORAGE_KEY = "otklik_cookie_choice_v1";

export function CookieBanner() {
  const [visible, setVisible] = useState(false);
  const [saved, setSaved] = useState<"all" | "essential" | null>(null);

  useEffect(() => {
    try {
      const stored = window.localStorage.getItem(STORAGE_KEY);
      if (!stored) setVisible(true);
      else setSaved(stored === "all" ? "all" : "essential");
    } catch {
      setVisible(true);
    }
  }, []);

  function choose(value: "all" | "essential") {
    try {
      window.localStorage.setItem(STORAGE_KEY, value);
    } catch {
      // Приватный режим: выбор не сохранится, но интерфейс продолжит работать.
    }
    setSaved(value);
    setVisible(false);
  }

  if (!visible) return null;

  return (
    <section
      aria-label="Согласие на использование файлов cookie"
      role="region"
      className="fixed inset-x-0 bottom-0 z-40 border-t border-line bg-white shadow-[0_-8px_24px_rgba(8,39,66,0.08)]"
    >
      <div className="mx-auto flex w-full max-w-6xl flex-col gap-4 px-4 py-4 sm:px-6 lg:flex-row lg:items-center lg:justify-between">
        <div className="max-w-3xl">
          <p className="text-sm font-semibold text-ink">
            Только необходимые cookie — без рекламы и слежки
          </p>
          <p className="mt-1 text-xs leading-relaxed text-muted">
            Мы используем одну сессионную cookie для входа. Аналитики, рекламных пикселей и
            сторонних SDK нет. Подробнее —{" "}
            <Link href="/legal/cookies" className="font-medium underline underline-offset-2">
              в политике cookie
            </Link>
            .
          </p>
        </div>
        <div className="flex flex-col gap-2 sm:flex-row">
          <button type="button" onClick={() => choose("essential")} className="btn btn-secondary">
            Только необходимые
          </button>
          <button type="button" onClick={() => choose("all")} className="btn btn-primary">
            Принять все
          </button>
        </div>
      </div>
      <p className="sr-only" aria-live="polite">
        {saved ? "Выбор сохранён" : ""}
      </p>
    </section>
  );
}

import { headers } from "next/headers";
import { prisma } from "./db";

type Bucket = { count: number; resetAt: number; blockedUntil: number };

const buckets = new Map<string, Bucket>();

export type RateLimitResult = {
  allowed: boolean;
  remaining: number;
  retryAfterSeconds: number;
};

/**
 * Простой ограничитель в памяти процесса. Для одного демо-стенда этого достаточно;
 * в промышленной эксплуатации лимит выносится в Redis или БД.
 */
export function rateLimit(
  key: string,
  { limit, windowMs, blockMs = windowMs }: { limit: number; windowMs: number; blockMs?: number },
): RateLimitResult {
  const now = Date.now();
  if (buckets.size > 5000) {
    for (const [bucketKey, bucket] of buckets) {
      if (bucket.resetAt < now && bucket.blockedUntil < now) buckets.delete(bucketKey);
    }
  }

  const bucket = buckets.get(key) ?? { count: 0, resetAt: now + windowMs, blockedUntil: 0 };

  if (bucket.blockedUntil > now) {
    buckets.set(key, bucket);
    return {
      allowed: false,
      remaining: 0,
      retryAfterSeconds: Math.ceil((bucket.blockedUntil - now) / 1000),
    };
  }

  if (bucket.resetAt <= now) {
    bucket.count = 0;
    bucket.resetAt = now + windowMs;
  }

  bucket.count += 1;
  if (bucket.count > limit) {
    bucket.blockedUntil = now + blockMs;
    buckets.set(key, bucket);
    return {
      allowed: false,
      remaining: 0,
      retryAfterSeconds: Math.ceil(blockMs / 1000),
    };
  }

  buckets.set(key, bucket);
  return { allowed: true, remaining: Math.max(0, limit - bucket.count), retryAfterSeconds: 0 };
}

export function resetRateLimit(key: string) {
  buckets.delete(key);
}

export async function getClientIp(): Promise<string> {
  const store = await headers();
  const forwarded = store.get("x-forwarded-for");
  if (forwarded) return forwarded.split(",")[0]?.trim() || "unknown";
  return store.get("x-real-ip") ?? "unknown";
}

/** Запись в журнал безопасности. Ошибка журнала не должна ломать основное действие. */
export async function recordAudit(entry: {
  action: string;
  userId?: string | null;
  email?: string | null;
  meta?: Record<string, unknown>;
}) {
  try {
    const store = await headers();
    await prisma.auditLog.create({
      data: {
        action: entry.action,
        userId: entry.userId ?? null,
        email: entry.email?.slice(0, 200) ?? null,
        ip: (await getClientIp()).slice(0, 64),
        userAgent: (store.get("user-agent") ?? "").slice(0, 300) || null,
        meta: entry.meta ? JSON.stringify(entry.meta).slice(0, 2000) : null,
      },
    });
  } catch {
    // Журнал не должен блокировать работу пользователя.
  }
}

/** Проверка загружаемого файла: расширение, MIME и сигнатура. */
export const UPLOAD_LIMIT_BYTES = 5 * 1024 * 1024;

const ALLOWED_EXTENSIONS = new Set([
  "pdf",
  "png",
  "jpg",
  "jpeg",
  "webp",
  "txt",
  "csv",
  "doc",
  "docx",
  "xls",
  "xlsx",
  "odt",
  "ods",
]);

const ALLOWED_MIME = new Set([
  "application/pdf",
  "image/png",
  "image/jpeg",
  "image/webp",
  "text/plain",
  "text/csv",
  "application/msword",
  "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
  "application/vnd.ms-excel",
  "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
  "application/vnd.oasis.opendocument.text",
  "application/vnd.oasis.opendocument.spreadsheet",
  "application/octet-stream",
]);

export function validateUploadName(fileName: string): string | null {
  const extension = fileName.split(".").pop()?.toLowerCase() ?? "";
  if (!ALLOWED_EXTENSIONS.has(extension)) {
    return "Формат файла не поддерживается. Разрешены PDF, изображения, TXT, CSV, DOC(X), XLS(X), ODT/ODS.";
  }
  return null;
}

export function validateUploadMime(mime: string): string | null {
  if (!mime) return null;
  if (!ALLOWED_MIME.has(mime)) {
    return "Тип файла не разрешён. Загрузите документ или изображение.";
  }
  return null;
}

/**
 * Проверка сигнатуры для самых опасных форматов. Для офисных документов
 * сигнатура ZIP (PK) допустима; исполняемые файлы отсекаются по расширению и MIME.
 */
export function validateUploadSignature(bytes: Uint8Array): string | null {
  const startsWith = (signature: number[]) =>
    signature.every((value, index) => bytes[index] === value);

  if (startsWith([0x4d, 0x5a])) return "Исполняемые файлы запрещены.";
  if (startsWith([0x7f, 0x45, 0x4c, 0x46])) return "Исполняемые файлы запрещены.";
  if (startsWith([0x23, 0x21])) return "Скрипты запрещены.";
  return null;
}

export function safeFileName(name: string): string {
  const base = name.split(/[\\/]/).pop() ?? "file";
  return base.replace(/[^\p{L}\p{N}._-]+/gu, "_").slice(-120) || "file";
}

"use server";

import { redirect } from "next/navigation";
import { z } from "zod";
import { prisma } from "@/lib/db";
import { getClientIp, rateLimit, recordAudit } from "@/lib/security";

const requestSchema = z.object({
  name: z.string().trim().min(2, "Укажите имя").max(120),
  email: z.string().trim().toLowerCase().email("Проверьте адрес почты").max(200),
  kind: z.enum(["access", "delete", "correct", "withdraw"], {
    message: "Выберите тип запроса",
  }),
  message: z.string().trim().min(10, "Опишите запрос подробнее").max(4000),
  consent: z.literal("on", { message: "Нужно согласие на обработку данных" }),
  adult: z.literal("on", { message: "Подтвердите, что вам 18 лет или больше" }),
});

export async function submitDataRequest(formData: FormData) {
  const ip = await getClientIp();
  const limit = rateLimit(`data-request:${ip}`, {
    limit: 3,
    windowMs: 60 * 60 * 1000,
    blockMs: 60 * 60 * 1000,
  });
  if (!limit.allowed) redirect("/data-request?error=rate");

  const parsed = requestSchema.safeParse({
    name: formData.get("name"),
    email: formData.get("email"),
    kind: formData.get("kind"),
    message: formData.get("message"),
    consent: formData.get("consent"),
    adult: formData.get("adult"),
  });

  if (!parsed.success) {
    const first = parsed.error.issues[0]?.message ?? "Проверьте поля формы";
    redirect(`/data-request?error=${encodeURIComponent(first)}`);
  }

  const data = parsed.data;

  try {
    const request = await prisma.dataRequest.create({ data });
    await recordAudit({
      action: "data_request.created",
      email: data.email,
      meta: { kind: data.kind, requestId: request.id },
    });

    const admins = await prisma.user.findMany({
      where: { role: "admin" },
      select: { id: true },
    });
    if (admins.length) {
      await prisma.notification.createMany({
        data: admins.map((admin) => ({
          userId: admin.id,
          event: "data_request",
          message: `Запрос по персональным данным (${data.kind}) от ${data.email}`,
        })),
      });
    }
  } catch {
    redirect("/data-request?error=server");
  }

  redirect("/data-request?sent=1");
}

