"use client";

import Link from "next/link";
import { usePathname } from "next/navigation";

type NavItem = { href: string; label: string; badge?: number };

export function Nav({ items }: { items: NavItem[] }) {
  const pathname = usePathname();

  return (
    <nav aria-label="Основная навигация" className="flex flex-nowrap items-center gap-1">
      {items.map((item) => {
        const active = pathname === item.href || pathname.startsWith(`${item.href}/`);
        return (
          <Link
            key={item.href}
            href={item.href}
            aria-current={active ? "page" : undefined}
            className={[
              "inline-flex min-h-11 items-center whitespace-nowrap rounded px-3 py-1.5 text-sm transition-colors",
              active
                ? "bg-white/15 font-semibold text-white"
                : "text-white/75 hover:bg-white/10 hover:text-white",
            ].join(" ")}
          >
            {item.label}
            {item.badge ? (
              <span className="ml-1.5 inline-flex h-4 min-w-4 items-center justify-center rounded-full bg-brand-red px-1 text-[10px] font-bold text-white">
                {item.badge}
              </span>
            ) : null}
          </Link>
        );
      })}
    </nav>
  );
}

"use server";

import { revalidatePath } from "next/cache";
import { z } from "zod";
import { requireUser } from "@/lib/auth";
import { prisma } from "@/lib/db";
import { recordAudit } from "@/lib/security";

const settingsSchema = z.object({
  notifyInApp: z.boolean(),
  notifyEmail: z.boolean(),
});

export async function updateNotificationSettings(formData: FormData) {
  const user = await requireUser();
  const parsed = settingsSchema.safeParse({
    notifyInApp: formData.get("notifyInApp") === "on",
    notifyEmail: formData.get("notifyEmail") === "on",
  });
  if (!parsed.success) return;

  await prisma.user.update({
    where: { id: user.id },
    data: parsed.data,
  });
  await recordAudit({
    action: "settings.notifications",
    userId: user.id,
    meta: parsed.data,
  });
  revalidatePath("/settings");
}

export async function unsubscribeAll() {
  const user = await requireUser();
  await prisma.user.update({
    where: { id: user.id },
    data: { notifyEmail: false, notifyInApp: false },
  });
  await recordAudit({ action: "settings.unsubscribe", userId: user.id });
  revalidatePath("/settings");
}

