export const dynamic = "force-dynamic";

/** Похожие обращения для шага «Описание». Только доступные пользователю записи. */
export async function GET(request: Request) {
  const user = await getCurrentUser();
  if (!user) {
    return NextResponse.json({ items: [] }, { status: 401 });
  }

  const limit = rateLimit(`similar:${user.id}`, { limit: 40, windowMs: 60_000 });
  if (!limit.allowed) {
    return NextResponse.json(
      { items: [], error: "rate" },
      { status: 429, headers: { "Retry-After": String(limit.retryAfterSeconds) } },
    );
  }

  const query = new URL(request.url).searchParams.get("q")?.trim().slice(0, 300) ?? "";
  if (query.length < 12) {
    return NextResponse.json({ items: [] });
  }

  const appeals = await prisma.appeal.findMany({
    where: {
      AND: [
        visibleWhere(user),
        {
          OR: [
            { text: { contains: query } },
            { proposal: { contains: query } },
            { code: { contains: query } },
          ],
        },
      ],
    },
    select: {
      id: true,
      code: true,
      status: true,
      text: true,
      category: { select: { name: true } },
      customCategory: true,
    },
    orderBy: { createdAt: "desc" },
    take: 4,
  });

  return NextResponse.json({
    items: appeals.map((appeal) => ({
      id: appeal.id,
      code: appeal.code,
      status: statusLabel(appeal.status),
      category: appeal.customCategory ?? appeal.category.name,
      excerpt: appeal.text.replace(/\s+/g, " ").slice(0, 120),
    })),
  });
}

import { buildListWhere, parseFilters } from "@/lib/appeals";
import { requireUser } from "@/lib/auth";
import { prisma } from "@/lib/db";
import { rateLimit } from "@/lib/security";
import { priorityLabel, statusLabel, typeLabel } from "@/lib/constants";
import { formatDate } from "@/lib/format";

export const dynamic = "force-dynamic";

/**
 * CSV-выгрузка обращений, доступных пользователю.
 * BOM нужен Excel для корректной кириллицы. Значения, начинающиеся с =,+,-,@,
 * экранируются, чтобы Excel не выполнил их как формулу.
 */
function csvCell(value: string | number | null | undefined): string {
  const raw = value == null ? "" : String(value);
  const guarded = /^[=+\-@\t\r]/.test(raw) ? `'${raw}` : raw;
  return `"${guarded.replace(/"/g, '""')}"`;
}

export async function GET(request: Request) {
  const user = await requireUser();

  const limit = rateLimit(`export:${user.id}`, { limit: 6, windowMs: 10 * 60 * 1000 });
  if (!limit.allowed) {
    return new Response("Слишком много выгрузок. Попробуйте позже.", {
      status: 429,
      headers: { "Retry-After": String(limit.retryAfterSeconds) },
    });
  }

  const url = new URL(request.url);
  const params: Record<string, string> = {};
  for (const [key, value] of url.searchParams.entries()) params[key] = value;
  const filters = parseFilters(params);

  const appeals = await prisma.appeal.findMany({
    where: buildListWhere(user, filters),
    include: {
      category: true,
      department: true,
      author: true,
      assignee: true,
    },
    orderBy: { createdAt: "desc" },
    take: 1000,
  });

  const header = [
    "Номер",
    "Статус",
    "Тип",
    "Категория",
    "Приоритет",
    "Автор",
    "Отдел",
    "Исполнитель",
    "Создано",
    "Срок",
    "Текст",
    "Итог",
  ];

  const rows = appeals.map((appeal) => [
    appeal.code,
    statusLabel(appeal.status),
    typeLabel(appeal.type),
    appeal.customCategory ?? appeal.category.name,
    priorityLabel(appeal.priority),
    appeal.author.name,
    appeal.department?.name ?? "",
    appeal.assignee?.name ?? "",
    formatDate(appeal.publishedAt),
    appeal.deadline ? formatDate(appeal.deadline) : "",
    appeal.text.replace(/\s+/g, " "),
    (appeal.result ?? "").replace(/\s+/g, " "),
  ]);

  const csv = `\uFEFF${[header, ...rows].map((row) => row.map(csvCell).join(";")).join("\r\n")}`;
  const stamp = new Date().toISOString().slice(0, 10);

  return new Response(csv, {
    headers: {
      "Content-Type": "text/csv; charset=utf-8",
      "Content-Disposition": `attachment; filename="otklik-appeals-${stamp}.csv"`,
      "Cache-Control": "no-store",
      "X-Content-Type-Options": "nosniff",
    },
  });
}

